"""Corner-case generator: degenerate rows, boundaries and odd lifecycles."""
import random

PAD = 1514


def value(rng):
    return rng.choice([rng.randint(0, 1513), rng.randint(1515, 3028),
                       rng.randint(1400, 1700), 1514, 0, 3028])


def row_values(rng, low, high):
    """A row with padding allowed anywhere; the validator enforces the suffix."""
    out = []
    for _ in range(rng.randint(low, high)):
        value = rng.choice([rng.randint(1400, 1700), rng.randint(1000, 2600),
                            rng.randint(0, 3028), PAD])
        if value == PAD:
            out.append(PAD)
            break
        out.append(value)
    if len(out) < low:
        out.extend([1600 + i for i in range(low - len(out))])
    return out


def make_release(rng, index):
    classes = rng.randint(1, 3)
    width = rng.randint(2, 5)
    discovery = []
    for _ in range(rng.randint(0, 12)):
        cls = rng.randrange(classes)
        values = row_values(rng, 2, 9)
        style = rng.random()
        if style < 0.2:
            acts = [rng.choice([0, 1]) for _ in values]
        elif style < 0.4:
            acts = [7] * len(values)
        elif style < 0.7:
            acts = [0] * len(values)
            start = rng.randrange(len(values))
            for position in range(start, min(len(values), start + rng.randint(1, 6))):
                acts[position] = 1000
        else:
            acts = [rng.choice([0, 0, 5, 900, 1000]) for _ in values]
        discovery.append({'class': cls, 'values': values, 'activation': acts})
    train = []
    validation = []
    for cls in range(classes):
        for _ in range(rng.randint(1, 3)):
            train.append({'class': cls, 'values': row_values(rng, 0, 8)})
        for _ in range(rng.randint(1, 4)):
            validation.append({'class': cls, 'values': row_values(rng, 0, 10)})
    rng.shuffle(train)
    rng.shuffle(validation)
    return {'id': 'r%d' % index, 'classes': classes, 'width': width,
            'eps': rng.choice([[0, 1], [1, 1], [1, 3], [7, 5], [100, 1], [1, 1000000],
                               [1000000, 1000000]]),
            'ratio': rng.choice([[0, 1], [1, 1], [1, 2], [2, 3], [999999, 1000000]]),
            'threshold': rng.choice([[0, 1], [1, 1], [1, 1000000], [1000000, 1],
                                     [999999, 1], [2, 1]]),
            'mode': rng.choice(['range', 'exact']),
            'packet_limit': rng.choice([width, width + 1, 3, 5]),
            'idle_us': rng.choice([0, 1, 3, 10 ** 12]),
            'discovery': discovery, 'train': train, 'validation': validation}


def make_request(seed):
    rng = random.Random(seed)
    specs = [make_release(rng, i) for i in range(rng.randint(1, 3))]
    capacity = {'range': rng.choice([0, 1, 2, 4096]),
                'exact': rng.choice([0, 1, 2, 8192])}
    ids = [spec['id'] for spec in specs]
    ops = []
    active = []
    stamps = {}
    for _ in range(rng.randint(2, 40)):
        roll = rng.random()
        if roll < 0.2 or not ids:
            ops.append(['install', rng.choice(ids)])
        elif roll < 0.35:
            flow = 'f%d' % rng.randint(0, 3)
            if flow in active:
                continue
            ops.append(['open', flow])
            active.append(flow)
            stamps[flow] = rng.choice([0, 5])
        elif roll < 0.8 and active:
            flow = rng.choice(active)
            stamps[flow] += rng.choice([0, 0, 1, 2, 5])
            ops.append(['packet', flow, stamps[flow], rng.randint(0, 1),
                        rng.choice([1, 2, 86, 1513, 1514])])
        elif active:
            flow = rng.choice(active)
            ops.append(['close', flow])
            active.remove(flow)
    for flow in active:
        ops.append(['close', flow])
    blocks = []
    while ops:
        size = rng.randint(1, 4)
        blocks.append(ops[:size])
        ops = ops[size:]
    return {'capacity': capacity, 'releases': specs, 'blocks': blocks}
